, '')) FILTER (WHERE (TRUE AND (("f30" = 'Mastercard')))) AS "segment_part_9001", COUNT(DISTINCT NULLIF(TRIM("email"), '')) FILTER (WHERE (TRUE AND (("f18" = 'Delhi')))) AS "segment_part_9002", COUNT(DISTINCT NULLIF(TRIM("email"), '')) FILTER (WHERE (TRUE AND (("f30" = 'Mastercard') AND ("f31" > 51)))) AS "segment_part_488", COUNT(DISTINCT NULLIF(TRIM("email"), '')) FILTER (WHERE (TRUE AND (("f30" = 'Mastercard') AND ("f31" > 51)))) AS "exclude_segments", COUNT(DISTINCT NULLIF(TRIM("email"), '')) FILTER (WHERE (TRUE AND ((("f2" IN (SELECT unique_identifier FROM _bf WHERE block_file_id IN (56))))))) AS "include_block_files", COUNT(DISTINCT NULLIF(TRIM("email"), '')) FILTER (WHERE (TRUE AND ((("f2" IN (SELECT unique_identifier FROM _bf WHERE block_file_id IN (56))))))) AS "block_part_56", COUNT(DISTINCT NULLIF(TRIM("email"), '')) FILTER (WHERE (TRUE AND ((("f2" IN (SELECT unique_identifier FROM _bf WHERE block_file_id IN (57))))))) AS "block_part_57", COUNT(DISTINCT NULLIF(TRIM("email"), '')) FILTER (WHERE (TRUE AND ((("f2" IN (SELECT unique_identifier FROM _bf WHERE block_file_id IN (57))))))) AS "exclude_block_files", COUNT(DISTINCT NULLIF(TRIM("email"), '')) FILTER (WHERE ((TRUE AND ((("f30" = 'Mastercard')) OR (("f18" = 'Delhi')))) OR (TRUE AND ((("f2" IN (SELECT unique_identifier FROM _bf WHERE block_file_id IN (56)))))))) AS "include_base", COUNT(DISTINCT NULLIF(TRIM("email"), '')) FILTER (WHERE ((TRUE AND ((("f30" = 'Mastercard')) OR (("f18" = 'Delhi'))) AND (NOT (("f30" = 'Mastercard') AND ("f31" > 51))) AND ((NOT ("f2" IN (SELECT unique_identifier FROM _bf WHERE block_file_id IN (57)))))) OR (TRUE AND ((("f2" IN (SELECT unique_identifier FROM _bf WHERE block_file_id IN (56))))) AND (NOT (("f30" = 'Mastercard') AND ("f31" > 51))) AND ((NOT ("f2" IN (SELECT unique_identifier FROM _bf WHERE block_file_id IN (57)))))))) AS "final_target" FROM _c
